+@page "/book-appointment"
+@rendermode InteractiveServer
+@using sv_ec20ffee166c47d1a404ecc053ff1051.Services
+@inject AppointmentService AppointmentService
+
+<PageTitle>Book Appointment</PageTitle>
+
+<h3 class="mb-4">Book an Appointment</h3>
+
+<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
+    <DataAnnotationsValidator />
+
+    @* ───── STEP 1: Patient Information ───── *@
+    <div class="card mb-4">
+        <div class="card-header"><strong>Step 1 — Patient Information</strong></div>
+        <div class="card-body">
+            <div class="mb-3">
+                <label class="form-label" for="patientName">Patient Name</label>
+                <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
+                <ValidationMessage For="() => Model.PatientName" />
+                @if (_serverErrors.ContainsKey(nameof(Model.PatientName)))
+                {
+                    <div class="validation-message">@_serverErrors[nameof(Model.PatientName)]</div>
+                }
+            </div>
+
+            <div class="mb-3">
+                <label class="form-label" for="email">Email</label>
+                <InputText id="email" class="form-control" @bind-Value="Model.Email" />
+                <ValidationMessage For="() => Model.Email" />
+                @if (_serverErrors.ContainsKey(nameof(Model.Email)))
+                {
+                    <div class="validation-message">@_serverErrors[nameof(Model.Email)]</div>
+                }
+            </div>
+
+            <div class="mb-3">
+                <label class="form-label" for="phone">Phone</label>
+                <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
+                <ValidationMessage For="() => Model.Phone" />
+                @if (_serverErrors.ContainsKey(nameof(Model.Phone)))
+                {
+                    <div class="validation-message">@_serverErrors[nameof(Model.Phone)]</div>
+                }
+            </div>
+
+            <div class="mb-3">
+                <label class="form-label" for="insurance">Insurance Provider</label>
+                <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
+                    <option value="">-- Select --</option>
+                    <option value="Aetna">Aetna</option>
+                    <option value="BlueCross">BlueCross</option>
+                    <option value="Cigna">Cigna</option>
+                    <option value="UnitedHealth">UnitedHealth</option>
+                    <option value="None">None</option>
+                </InputSelect>
+                <ValidationMessage For="() => Model.InsuranceProvider" />
+                @if (_serverErrors.ContainsKey(nameof(Model.InsuranceProvider)))
+                {
+                    <div class="validation-message">@_serverErrors[nameof(Model.InsuranceProvider)]</div>
+                }
+            </div>
+
+            @if (!_showStep2)
+            {
+                <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
+                    Continue to Step 2
+                </button>
+            }
+        </div>
+    </div>
+
+    @* ───── STEP 2: Appointment Details ───── *@
+    @if (_showStep2)
+    {
+        <div class="card mb-4">
+            <div class="card-header"><strong>Step 2 — Appointment Details</strong></div>
+            <div class="card-body">
+                <div class="mb-3">
+                    <label class="form-label" for="doctor">Preferred Doctor</label>
+                    <InputSelect id="doctor" class="form-select" @bind-Value="Model.PreferredDoctor"
+                                 @bind-Value:after="OnDoctorOrDateChanged">
+                        <option value="">-- Select --</option>
+                        @foreach (var doc in _doctors)
+                        {
+                            <option value="@doc">@doc</option>
+                        }
+                    </InputSelect>
+                    <ValidationMessage For="() => Model.PreferredDoctor" />
+                    @if (_serverErrors.ContainsKey(nameof(Model.PreferredDoctor)))
+                    {
+                        <div class="validation-message">@_serverErrors[nameof(Model.PreferredDoctor)]</div>
+                    }
+                </div>
+
+                <div class="mb-3">
+                    <label class="form-label" for="date">Date</label>
+                    <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
+                               @bind-Value:after="OnDoctorOrDateChanged" />
+                    <ValidationMessage For="() => Model.AppointmentDate" />
+                    @if (_serverErrors.ContainsKey(nameof(Model.AppointmentDate)))
+                    {
+                        <div class="validation-message">@_serverErrors[nameof(Model.AppointmentDate)]</div>
+                    }
+                </div>
+
+                <div class="mb-3">
+                    <label class="form-label" for="timeslot">Time Slot</label>
+                    <InputSelect id="timeslot" class="form-select" @bind-Value="Model.TimeSlot">
+                        <option value="">-- Select --</option>
+                        @foreach (var slot in _timeSlots)
+                        {
+                            <option value="@slot">@slot</option>
+                        }
+                    </InputSelect>
+                    <ValidationMessage For="() => Model.TimeSlot" />
+                    @if (_serverErrors.ContainsKey(nameof(Model.TimeSlot)))
+                    {
+                        <div class="validation-message">@_serverErrors[nameof(Model.TimeSlot)]</div>
+                    }
+                </div>
+
+                <div class="mb-3">
+                    <label class="form-label" for="reason">Reason for Visit</label>
+                    <InputTextArea id="reason" class="form-control" rows="3"
+                                   @bind-Value="Model.ReasonForVisit" />
+                    <ValidationMessage For="() => Model.ReasonForVisit" />
+                    @if (_serverErrors.ContainsKey(nameof(Model.ReasonForVisit)))
+                    {
+                        <div class="validation-message">@_serverErrors[nameof(Model.ReasonForVisit)]</div>
+                    }
+                </div>
+
+                <button type="button" class="btn btn-outline-secondary me-2" @onclick="BackToStep1">
+                    Back
+                </button>
+                <button type="button" class="btn btn-warning me-2" @onclick="CheckAvailability"
+                        disabled="@_isChecking">
+                    @(_isChecking ? "Checking…" : "Check Availability")
+                </button>
+                @if (_availabilityChecked && !_serverErrors.Any())
+                {
+                    <button type="submit" class="btn btn-success">
+                        Confirm Appointment
+                    </button>
+                }
+            </div>
+        </div>
+    }
+</EditForm>
+
+@if (_submitted)
+{
+    <div class="alert alert-success mt-3">
+        Appointment booked successfully for <strong>@Model.PatientName</strong> with
+        <strong>@Model.PreferredDoctor</strong> on @Model.AppointmentDate?.ToString("MMMM d, yyyy")
+        at @Model.TimeSlot.
+    </div>
+}
+
+@code {
+    private BookAppointmentModel Model { get; set; } = new();
+
+    private List<string> _doctors = [];
+    private List<string> _timeSlots = [];
+    private Dictionary<string, string> _serverErrors = new();
+
+    private bool _showStep2;
+    private bool _isChecking;
+    private bool _availabilityChecked;
+    private bool _submitted;
+
+    // ── Step 1 local validation ──
+    private bool ValidateStep1()
+    {
+        _serverErrors.Clear();
+
+        if (string.IsNullOrWhiteSpace(Model.PatientName))
+            _serverErrors[nameof(Model.PatientName)] = "Patient Name is required.";
+
+        if (string.IsNullOrWhiteSpace(Model.Email))
+            _serverErrors[nameof(Model.Email)] = "Email is required.";
+        else if (!System.Text.RegularExpressions.Regex.IsMatch(
+                     Model.Email, @"^[^@\s]+@[^@\s]+\.[^@\s]+$"))
+            _serverErrors[nameof(Model.Email)] = "Invalid email format.";
+
+        if (string.IsNullOrWhiteSpace(Model.Phone))
+            _serverErrors[nameof(Model.Phone)] = "Phone is required.";
+
+        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
+            _serverErrors[nameof(Model.InsuranceProvider)] = "Insurance Provider is required.";
+
+        return _serverErrors.Count == 0;
+    }
+
+    private async Task ProceedToStep2()
+    {
+        if (!ValidateStep1()) return;
+
+        _doctors = await AppointmentService.GetDoctorsAsync();
+        _showStep2 = true;
+    }
+
+    private void BackToStep1()
+    {
+        _showStep2 = false;
+        _availabilityChecked = false;
+        _serverErrors.Clear();
+    }
+
+    // ── Reload time slots when doctor or date changes ──
+    private async Task OnDoctorOrDateChanged()
+    {
+        _availabilityChecked = false;
+        _serverErrors.Remove(nameof(Model.PreferredDoctor));
+        _serverErrors.Remove(nameof(Model.TimeSlot));
+        Model.TimeSlot = string.Empty;
+
+        if (!string.IsNullOrEmpty(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
+        {
+            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
+                Model.PreferredDoctor, Model.AppointmentDate.Value);
+        }
+        else
+        {
+            _timeSlots = [];
+        }
+    }
+
+    // ── Step 2 local + server validation via "Check Availability" ──
+    private async Task CheckAvailability()
+    {
+        _serverErrors.Clear();
+        _availabilityChecked = false;
+
+        // Local validation for step-2 fields
+        if (string.IsNullOrWhiteSpace(Model.PreferredDoctor))
+            _serverErrors[nameof(Model.PreferredDoctor)] = "Preferred Doctor is required.";
+
+        if (!Model.AppointmentDate.HasValue)
+            _serverErrors[nameof(Model.AppointmentDate)] = "Date is required.";
+        else if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
+            _serverErrors[nameof(Model.AppointmentDate)] = "Date must be in the future.";
+
+        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
+            _serverErrors[nameof(Model.TimeSlot)] = "Time Slot is required.";
+
+        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
+            _serverErrors[nameof(Model.ReasonForVisit)] = "Reason for Visit is required.";
+        else if (Model.ReasonForVisit.Length > 500)
+            _serverErrors[nameof(Model.ReasonForVisit)] = "Reason must be 500 characters or fewer.";
+
+        if (_serverErrors.Any()) return;
+
+        // Server-side validation
+        _isChecking = true;
+        try
+        {
+            var result = await AppointmentService.ValidatePatientAsync(
+                Model.Email, Model.InsuranceProvider, Model.PreferredDoctor, Model.TimeSlot);
+
+            foreach (var kvp in result)
+                _serverErrors[kvp.Key] = kvp.Value;
+
+            _availabilityChecked = _serverErrors.Count == 0;
+        }
+        finally
+        {
+            _isChecking = false;
+        }
+    }
+
+    private void HandleSubmit()
+    {
+        if (!_availabilityChecked || _serverErrors.Any()) return;
+        _submitted = true;
+    }
+}
+

